// Custom and built-in bank exceptions
public class Q10 {static class InsufficientFundsException extends Exception {InsufficientFundsException(String m){super(m);}}static class BankAccount {double balance=1000;void withdraw(double amount)throws InsufficientFundsException {if(amount<0)throw new IllegalArgumentException("Amount cannot be negative");if(amount>balance)throw new InsufficientFundsException("Insufficient funds");balance-=amount;}}public static void main(String[] args){BankAccount b=new BankAccount();for(double amount:new double[]{1500,-20,200}){try{b.withdraw(amount);System.out.println("Remaining: "+b.balance);}catch(InsufficientFundsException|IllegalArgumentException e){System.out.println(e.getMessage());}}}}
